import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import ReferenceGraph from './ReferenceGraph';
export default class ReferenceGraphModal extends Modal {
  className() {
    return 'ReferenceGraphModal Modal--medium';
  }
  title() {
    return app.translator.trans('datlechin-references.forum.graph.title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("p", {
      className: "helpText"
    }, app.translator.trans('datlechin-references.forum.graph.description')), m(ReferenceGraph, {
      discussionId: this.attrs.discussionId
    }));
  }
}
flarum.reg.add('datlechin-references', 'forum/components/ReferenceGraphModal', ReferenceGraphModal);