import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import RemoteComponent from '../../common/components/RemoteComponent';
export default class RelatedDiscussions extends RemoteComponent {
  request() {
    return app.request({
      method: 'GET',
      url: `${app.forum.attribute('apiUrl')}/datlechin-references/related`,
      params: {
        id: this.attrs.discussionId
      }
    });
  }
  content(response) {
    if (!response.data.length) return null;
    return m("section", {
      className: "RelatedDiscussions"
    }, m("h3", {
      className: "RelatedDiscussions-title"
    }, app.translator.trans('datlechin-references.forum.related.title')), m("ul", {
      className: "ReferenceList"
    }, response.data.map(discussion => m("li", {
      key: discussion.id
    }, m(Link, {
      href: app.route('discussion', {
        id: discussion.slug
      }),
      className: "ReferenceList-link"
    }, m("span", {
      className: "ReferenceList-title"
    }, discussion.title))))));
  }
}
flarum.reg.add('datlechin-references', 'forum/components/RelatedDiscussions', RelatedDiscussions);