import app from 'flarum/forum/app';
/**
 * A plain `references` row says nothing a reader needs, so it shows nothing.
 * Only a moderator's classification earns a label.
 */
export default function relationLabel(reference) {
  const relation = reference.relationType();
  if (!relation || relation === 'references') return null;
  return m("span", {
    className: "ReferenceList-relation"
  }, app.translator.trans(`datlechin-references.forum.relation.${relation}`));
}
flarum.reg.add('datlechin-references', 'forum/utils/relationLabel', relationLabel);